function validate(uc) {
  const missing = [];
  if (!uc.actor) missing.push("actor");
  if (!uc.goal) missing.push("goal");
  if (!uc.steps || uc.steps.length === 0) missing.push("steps");
  return missing.length === 0 ? "VALID" : "Missing: " + missing.join(", ");
}
const draft = { actor: "Earner", steps: ["complete task"] };
console.log(validate(draft));

